    # --- формы количества и подписи приёмов пищи ----------------------------
    ('/** «1 штука / 2 штуки / 5 штук» — с запасом для нестандартных подписей. */\nconst pieceForms: Record<string, [string, string, string]> = { "штука": ["штука", "штуки", "штук"], "банка": ["банка", "банки", "банок"], "стакан": ["стакан", "стакана", "стаканов"], "порция": ["порция", "порции", "порций"] };\nconst pieceWord = (count: number, label: string) => { const forms = pieceForms[label] ?? [label, label, label]; const mod10 = count % 10; const mod100 = count % 100; const form = mod10 === 1 && mod100 !== 11 ? forms[0] : mod10 >= 2 && mod10 <= 4 && (mod100 < 12 || mod100 > 14) ? forms[1] : forms[2]; return `${count} ${form}`; };\n/** Компактная подпись количества: «3 шт», «2 банки», «1 порция». */\nconst pieceShort = (count: number, label: string) => label === "штука" ? `${count} шт` : pieceWord(count, label);',
     '/** «1 штука / 2 штуки / 5 штук» — ключи словаря для трёх форм числа. */\nconst PIECE_FORM_KEYS: Record<string, [DictKey, DictKey, DictKey]> = { "штука": ["nutrition.piece.piece.one", "nutrition.piece.piece.few", "nutrition.piece.piece.many"], "банка": ["nutrition.piece.can.one", "nutrition.piece.can.few", "nutrition.piece.can.many"], "стакан": ["nutrition.piece.glass.one", "nutrition.piece.glass.few", "nutrition.piece.glass.many"], "порция": ["nutrition.piece.serving.one", "nutrition.piece.serving.few", "nutrition.piece.serving.many"] };\n// Подписи приёмов пищи — в словаре: сам MealType остаётся значением данных.\nconst MEAL_KEYS: Record<MealType, DictKey> = { "Завтрак": "nutrition.meal.breakfast", "Обед": "nutrition.meal.lunch", "Ужин": "nutrition.meal.dinner", "Перекус": "nutrition.meal.snack" };\nconst WEEKDAY_KEYS = ["nutrition.weekday.mon", "nutrition.weekday.tue", "nutrition.weekday.wed", "nutrition.weekday.thu", "nutrition.weekday.fri", "nutrition.weekday.sat", "nutrition.weekday.sun"] as const;\nconst pieceWord = (count: number, label: string, t: TFunction) => { const keys = PIECE_FORM_KEYS[label]; const mod10 = count % 10; const mod100 = count % 100; const form = keys ? t(mod10 === 1 && mod100 !== 11 ? keys[0] : mod10 >= 2 && mod10 <= 4 && (mod100 < 12 || mod100 > 14) ? keys[1] : keys[2]) : label; return t("nutrition.piece.count", { count, form }); };\n/** Компактная подпись количества: «3 шт», «2 банки», «1 порция». */\nconst pieceShort = (count: number, label: string, t: TFunction) => label === defaultPieceLabel ? t("nutrition.piece.short", { count }) : pieceWord(count, label, t);'),
